import { createFileRoute, Link } from "@tanstack/react-router"

import { InstrumentDetail } from "@/components/instrument-detail"
import { buttonVariants } from "@/components/ui/button"
import {
  Empty,
  EmptyContent,
  EmptyDescription,
  EmptyHeader,
  EmptyTitle,
} from "@/components/ui/empty"
import { loadInstrument } from "@/server/functions"

export const Route = createFileRoute("/instruments/$symbol")({
  loader: ({ params }) => loadInstrument({ data: params.symbol }),
  component: InstrumentPage,
})

function InstrumentPage() {
  const { symbol } = Route.useParams()
  const instrument = Route.useLoaderData()

  if (!instrument) {
    return (
      <Empty>
        <EmptyHeader>
          <EmptyTitle>
            <h1>Instrument not found</h1>
          </EmptyTitle>
          <EmptyDescription>
            No instrument matches{" "}
            <span className="font-medium text-foreground">{symbol}</span>.
          </EmptyDescription>
        </EmptyHeader>
        <EmptyContent>
          <Link to="/" className={buttonVariants({ variant: "outline" })}>
            Back to instruments
          </Link>
        </EmptyContent>
      </Empty>
    )
  }

  return <InstrumentDetail instrument={instrument} />
}
import { useNavigate, useRouter } from "@tanstack/react-router"
import { useServerFn } from "@tanstack/react-start"
import { useState } from "react"

import { Button } from "@/components/ui/button"
import { selectPerson } from "@/server/functions"
import type { Person } from "@/server/people"

type SignInPanelProps = {
  people: readonly Person[]
}

export function SignInPanel({ people }: SignInPanelProps) {
  const choosePerson = useServerFn(selectPerson)
  const navigate = useNavigate()
  const router = useRouter()
  const [pendingId, setPendingId] = useState<string | null>(null)

  const handleSelect = async (personId: string) => {
    setPendingId(personId)
    try {
      await choosePerson({ data: personId })
      await router.invalidate()
      await navigate({ to: "/" })
    } finally {
      setPendingId(null)
    }
  }

  return (
    <div className="grid gap-3 sm:grid-cols-2">
      {people.map((person) => (
        <Button
          key={person.id}
          variant="outline"
          className="h-auto flex-col items-start gap-0.5 rounded-2xl px-4 py-3 text-left"
          disabled={pendingId !== null}
          onClick={() => void handleSelect(person.id)}
        >
          <span className="text-base">{person.displayName}</span>
          <span className="text-xs font-normal text-muted-foreground">
            {person.email}
          </span>
        </Button>
      ))}
    </div>
  )
}
import { Link, useRouter } from "@tanstack/react-router"
import { useServerFn } from "@tanstack/react-start"
import { useState } from "react"

import { ThemeToggle } from "@/components/theme-toggle"
import { Button, buttonVariants } from "@/components/ui/button"
import { clearPerson } from "@/server/functions"
import type { Person } from "@/server/people"

type SiteHeaderProps = {
  person: Person | null
}

export function SiteHeader({ person }: SiteHeaderProps) {
  const signOut = useServerFn(clearPerson)
  const router = useRouter()
  const [isSigningOut, setIsSigningOut] = useState(false)

  const handleSignOut = async () => {
    setIsSigningOut(true)
    try {
      await signOut()
      await router.invalidate()
    } finally {
      setIsSigningOut(false)
    }
  }

  return (
    <header className="border-b">
      <div className="mx-auto flex h-16 max-w-7xl items-center justify-between gap-4 px-4 sm:px-8">
        <Link to="/" className="font-heading text-sm font-semibold">
          Market Desk
        </Link>
        <div className="flex items-center gap-2">
          <ThemeToggle />
          {person ? (
            <>
              <div className="mr-2 text-right">
                <p className="text-sm font-medium">{person.displayName}</p>
                <p className="hidden text-xs text-muted-foreground sm:block">
                  {person.email}
                </p>
              </div>
              <Link
                to="/sign-in"
                className={buttonVariants({ variant: "ghost" })}
              >
                Switch
              </Link>
              <Button
                variant="outline"
                disabled={isSigningOut}
                onClick={() => void handleSignOut()}
              >
                {isSigningOut ? "Signing out" : "Sign out"}
              </Button>
            </>
          ) : (
            <Link to="/sign-in" className={buttonVariants()}>
              Sign in
            </Link>
          )}
        </div>
      </div>
    </header>
  )
}
import { Link } from "@tanstack/react-router"

import { buttonVariants } from "@/components/ui/button"
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card"
import { Separator } from "@/components/ui/separator"
import { formatPrice } from "@/lib/format-price"
import type { Instrument } from "@/server/instruments"

type InstrumentDetailProps = {
  instrument: Instrument
}

export function InstrumentDetail({ instrument }: InstrumentDetailProps) {
  return (
    <div className="mx-auto max-w-2xl space-y-4">
      <Link to="/" className={buttonVariants({ variant: "ghost", size: "sm" })}>
        Back to instruments
      </Link>
      <Card>
        <CardHeader>
          <CardTitle>
            <h1 className="text-2xl">{instrument.symbol}</h1>
          </CardTitle>
          <CardDescription>{instrument.name}</CardDescription>
        </CardHeader>
        <CardContent className="space-y-6">
          <div>
            <p className="text-muted-foreground">Last price</p>
            <p className="mt-1 text-4xl font-semibold tabular-nums">
              {formatPrice(instrument.last_price, instrument.decimals)}
              {instrument.currency ? (
                <span className="ml-2 text-base font-normal text-muted-foreground">
                  {instrument.currency}
                </span>
              ) : null}
            </p>
          </div>
          <Separator />
          <dl className="grid gap-4 sm:grid-cols-3">
            <DetailItem label="Asset class" value={instrument.asset_class} />
            <DetailItem label="Exchange" value={instrument.exchange} />
            <DetailItem
              label="Quote currency"
              value={instrument.currency ?? "—"}
            />
          </dl>
        </CardContent>
      </Card>
    </div>
  )
}

function DetailItem({ label, value }: { label: string; value: string }) {
  return (
    <div>
      <dt className="text-muted-foreground">{label}</dt>
      <dd className="mt-1 font-medium">{value}</dd>
    </div>
  )
}
export function formatPrice(value: number, decimals: number): string {
  return new Intl.NumberFormat("en-US", {
    maximumFractionDigits: decimals,
    minimumFractionDigits: decimals,
    useGrouping: false,
  }).format(value)
}

